<template>
  <main v-if="technician" class="technician-page">
    <header class="site-header"><RouterLink to="/technicians" class="back-link">&larr; Technicians</RouterLink><div class="header-actions"><a v-if="technician.socials?.linkedin" :href="technician.socials.linkedin" target="_blank" rel="noopener noreferrer" class="header-link">LinkedIn</a><span class="availability"><i></i>{{ technician.available ? 'Available for work' : 'Profile active' }}</span></div></header>
    <section class="hero section-shell"><div class="hero-copy"><p class="eyebrow">Oclok technician profile</p><h1>{{ technician.name }}</h1><p class="role">{{ technician.specialty }} <b>&bull;</b> {{ technician.experience || 0 }} years experience</p><p class="hero-intro">{{ technician.bio || 'A trusted Oclok professional delivering reliable work and thoughtful service.' }}</p><div class="hero-actions"><a class="button button-primary" :href="`mailto:${technician.contact.email}`">Contact Me <span>&rarr;</span></a><a v-if="technician.contact.phone" class="button button-outline" :href="`tel:${technician.contact.phone}`">Call <span>&rarr;</span></a><a class="text-link" href="#projects">View Projects &rarr;</a></div></div><div class="hero-visual"><div class="image-frame"><img :src="technician.image" :alt="`${technician.name} profile photo`" class="profile-image" @error="useFallbackImage" /></div><div class="location-card">&#9679; {{ technician.location || 'Kenya' }}</div></div></section>
    <section class="stats section-shell"><div class="stat"><strong>{{ technician.experience || 0 }}+</strong><span>Years experience</span></div><div class="stat"><strong>{{ completedProjects.length }}</strong><span>Completed projects</span></div><div class="stat"><strong>{{ ongoingProjects.length }}</strong><span>Active projects</span></div><div class="stat"><strong>{{ technician.available ? 'Open' : 'Active' }}</strong><span>Current status</span></div></section>
    <nav class="quick-nav section-shell"><a href="#summary">Profile</a><a href="#projects">Projects</a><a href="#skills">Capabilities</a><a href="#contact">Contact</a></nav>
    <section id="summary" class="content-section section-shell summary-grid"><div><p class="section-kicker">01 / Profile</p><h2>Work that earns<br /><em>confidence.</em></h2></div><div class="summary-copy"><p>{{ technician.bio || 'Experienced professional committed to quality, clear communication, and dependable delivery.' }}</p><p>Every project is approached with practical expertise, attention to detail, and a focus on outcomes that serve customers and teams well.</p><p class="pull-quote">Reliable service starts with people who care about the details.</p></div></section>
    <section id="projects" class="content-section section-shell"><div class="section-heading"><div><p class="section-kicker">02 / Selected work</p><h2>Projects and progress</h2></div><span class="section-number">02</span></div><div class="project-grid"><article v-for="project in allProjects" :key="project.title" class="project-card"><div class="project-topline"><span>{{ project.status }}</span><span>{{ project.index }}</span></div><h3>{{ project.title }}</h3><p>{{ project.status === 'Completed' ? 'Successfully delivered project work for an Oclok customer or partner.' : 'Current work being managed and delivered through the Oclok network.' }}</p><a class="text-link" href="#contact">Discuss project &rarr;</a></article><p v-if="!allProjects.length" class="empty-state">Projects will be added here as work is completed.</p></div></section>
    <section id="skills" class="content-section section-shell"><div class="section-heading"><div><p class="section-kicker">03 / Capabilities</p><h2>Where expertise meets action</h2></div><span class="section-number">03</span></div><div class="chip-list"><span v-for="skill in capabilities" :key="skill" class="chip">{{ skill }}</span></div></section>
    <section id="contact" class="contact-section section-shell"><div><p class="section-kicker">Let&apos;s connect</p><h2>Start with a<br /><em>conversation.</em></h2></div><div><p>Interested in working with {{ technician.name }}? Reach out directly to discuss a project, collaboration, or service request.</p><div class="contact-links"><a :href="`mailto:${technician.contact.email}`">Email <span>{{ technician.contact.email }}</span></a><a v-if="technician.contact.phone" :href="`tel:${technician.contact.phone}`">Phone <span>{{ technician.contact.phone }}</span></a><a v-if="technician.socials?.linkedin" :href="technician.socials.linkedin" target="_blank" rel="noopener noreferrer">LinkedIn <span>Connect online</span></a></div></div></section>
    <div class="cv-action"><button class="button button-primary" type="button" @click="downloadCv">Download CV <span>&darr;</span></button></div><footer class="page-footer section-shell"><span>{{ technician.name }} / {{ technician.location || 'Kenya' }}</span><a href="#summary">Back to top &uarr;</a></footer>
  </main>
  <div v-else class="not-found">Technician profile not found.</div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue';
import techniciansData from '../data/technicians.json';
import { applyProfileOverride } from '../services/userProfiles.service';

const technician = ref(null);
const route = window.location.pathname.split('/').filter(Boolean).pop() || '';
const fallbackImage = '/images/dokta.jpg';
const found = techniciansData.find((item) => item.slug === route || String(item.id) === route);
if (found) technician.value = applyProfileOverride(found);
const completedProjects = computed(() => technician.value?.projects?.completed || []);
const ongoingProjects = computed(() => technician.value?.projects?.continuing || []);
const allProjects = computed(() => [...ongoingProjects.value.map((title) => ({ title: typeof title === 'string' ? title : title.title, status: 'Ongoing' })), ...completedProjects.value.map((title) => ({ title: typeof title === 'string' ? title : title.title, status: 'Completed' }))].map((project, index) => ({ ...project, index: String(index + 1).padStart(2, '0') })));
const capabilities = computed(() => [technician.value?.specialty, 'Customer communication', 'Project delivery', 'Quality service', 'Oclok professional network'].filter(Boolean));
const useFallbackImage = (event) => { event.target.src = fallbackImage; };
onMounted(() => { if (technician.value) document.title = `${technician.value.name} | Oclok`; });
const downloadCv = () => {
  const name = (technician.value?.name || 'Technician')
    .trim()
    .replace(/[^a-z0-9]+/gi, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase();
  const filename = `${name || 'technician'}-cv`;
  const previousTitle = document.title;
  document.title = filename;
  window.print();
  document.title = previousTitle;
};
</script>

<style scoped>
