.cv-action{display:flex;justify-content:center;padding:1.5rem 0}.cv-action .button{border:0}.cv-action .button:hover{opacity:.9}@media print{.technician-page{max-width:none;padding:0;background:#fff}.site-header,.hero-visual,.quick-nav,.contact-section,.page-footer,.cv-action,.hero-actions,.text-link{display:none!important}.hero,.content-section,.stat{box-shadow:none;border:0;background:#fff}.hero{display:block;padding:0}.hero-copy{max-width:none}.stats{margin-top:1rem}.content-section{break-inside:avoid;margin-top:1rem;padding:1rem 0}.project-grid{grid-template-columns:repeat(2,1fr)}.chip{background:#fff}}
</style>
